int[] noten = { 2, 1, 3, 1, 4 };

Console.WriteLine(noten[0]);       // erstes Element
Console.WriteLine(noten[4]);       // letztes Element
Console.WriteLine(noten.Length);   // Anzahl der Elemente
// Ausgabe:
// 2
// 4
// 5

int[] punkte = new int[3];   // drei Fächer, alle 0
punkte[0] = 12;
punkte[2] = 7;
punkte[0] = punkte[0] + 3;   // Elemente lassen sich ändern

Console.WriteLine($"{punkte[0]} {punkte[1]} {punkte[2]}");
// Ausgabe: 15 0 7

// Werte direkt angeben geht auch so:
string[] tage = new string[] { "Mo", "Di", "Mi" };
Console.WriteLine(tage[1]);
// Ausgabe: Di

int[] noten = { 2, 1, 3, 1, 4 };
int summe = 0;

for (int i = 0; i < noten.Length; i++)
{
    Console.WriteLine($"Schularbeit {i + 1}: {noten[i]}");
    summe += noten[i];
}

Console.WriteLine($"Summe: {summe}");
// Ausgabe:
// Schularbeit 1: 2
// Schularbeit 2: 1
// Schularbeit 3: 3
// Schularbeit 4: 1
// Schularbeit 5: 4
// Summe: 11

string[] einkauf = { "Milch", "Brot", "Äpfel" };

foreach (string artikel in einkauf)
{
    Console.WriteLine($"- {artikel}");
}
// Ausgabe:
// - Milch
// - Brot
// - Äpfel

